-- =====================================================
--  MIGRACION 017 — Catalogo nacional de aldeas
--  SAG Honduras Sin Hambre · Junio 2026
--
--  Crea:
--    - sag_aldeas (CATALOGO NACIONAL, sin id_proyecto):
--      3,733 aldeas oficiales de Honduras vinculadas por
--      codigo_municipio al estandar INE.
--    - Agrega columna 'codigo' a sag_municipios y
--      sag_departamentos para poder vincular contra
--      el catalogo nacional.
--
--  Fuente:
--    Archivo XLSX oficial recibido por la SAG en Jun/2026:
--    "Departamentos_muni y aldeas oficial.xlsx"
--
--  Idempotente:
--    - Usa CREATE TABLE IF NOT EXISTS
--    - Usa ALTER TABLE con verificacion via stored procedure
--    - Usa INSERT IGNORE
--
--  APLICACION:
--    USE mddesarr_sag;
--    SOURCE migracion_017_aldeas_nacionales.sql;
--
--  ROLLBACK manual:
--    DROP TABLE IF EXISTS sag_aldeas;
--    ALTER TABLE sag_municipios DROP COLUMN codigo;
--    ALTER TABLE sag_departamentos DROP COLUMN codigo;
-- =====================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- -----------------------------------------------------
-- 1. Agregar 'codigo' a sag_departamentos (idempotente)
-- -----------------------------------------------------
DROP PROCEDURE IF EXISTS sp_017_add_col;
DELIMITER //
CREATE PROCEDURE sp_017_add_col(IN tbl VARCHAR(64), IN col VARCHAR(64), IN ddl TEXT)
BEGIN
    DECLARE col_exists INT DEFAULT 0;
    SELECT COUNT(*) INTO col_exists
      FROM information_schema.COLUMNS
     WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = tbl AND COLUMN_NAME = col;
    IF col_exists = 0 THEN
        SET @s = CONCAT('ALTER TABLE ', tbl, ' ADD COLUMN ', col, ' ', ddl);
        PREPARE stmt FROM @s; EXECUTE stmt; DEALLOCATE PREPARE stmt;
    END IF;
END //
DELIMITER ;

CALL sp_017_add_col('sag_departamentos', 'codigo', 'VARCHAR(4) NULL AFTER id_departamento');
CALL sp_017_add_col('sag_municipios',    'codigo', 'VARCHAR(8) NULL AFTER id_municipio');

DROP PROCEDURE IF EXISTS sp_017_add_col;

-- -----------------------------------------------------
-- 2. Tabla sag_aldeas (catalogo nacional, sin id_proyecto)
-- -----------------------------------------------------
CREATE TABLE IF NOT EXISTS sag_aldeas (
    id_aldea         INT             NOT NULL AUTO_INCREMENT PRIMARY KEY,
    codigo           VARCHAR(10)     NOT NULL,    -- '010101' (depto+muni+aldea)
    codigo_municipio VARCHAR(8)      NOT NULL,    -- '0101' vincula a sag_municipios.codigo
    nombre           VARCHAR(150)    NOT NULL,
    latitud          DECIMAL(10,6)       NULL,
    longitud         DECIMAL(10,6)       NULL,
    activo           TINYINT(1)      NOT NULL DEFAULT 1,
    created_at       TIMESTAMP       DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uk_codigo (codigo),
    INDEX idx_codigo_muni (codigo_municipio),
    INDEX idx_activo (activo)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


