-- -----------------------------------------------------
-- 4. Poblar 'codigo' en sag_departamentos y sag_municipios
--    a partir del catalogo oficial (match por nombre con
--    transliteracion para tolerar acentos y casing).
-- -----------------------------------------------------
-- Departamentos
UPDATE sag_departamentos SET codigo='01' WHERE codigo IS NULL AND UPPER(CONVERT(nombre USING ASCII))='ATLANTIDA';
UPDATE sag_departamentos SET codigo='02' WHERE codigo IS NULL AND UPPER(CONVERT(nombre USING ASCII))='COLON';
UPDATE sag_departamentos SET codigo='03' WHERE codigo IS NULL AND UPPER(CONVERT(nombre USING ASCII))='COMAYAGUA';
UPDATE sag_departamentos SET codigo='04' WHERE codigo IS NULL AND UPPER(CONVERT(nombre USING ASCII))='COPAN';
UPDATE sag_departamentos SET codigo='05' WHERE codigo IS NULL AND UPPER(CONVERT(nombre USING ASCII))='CORTES';
UPDATE sag_departamentos SET codigo='06' WHERE codigo IS NULL AND UPPER(CONVERT(nombre USING ASCII))='CHOLUTECA';
UPDATE sag_departamentos SET codigo='07' WHERE codigo IS NULL AND UPPER(CONVERT(nombre USING ASCII))='EL PARAISO';
UPDATE sag_departamentos SET codigo='08' WHERE codigo IS NULL AND UPPER(CONVERT(nombre USING ASCII))='FRANCISCO MORAZAN';
UPDATE sag_departamentos SET codigo='09' WHERE codigo IS NULL AND UPPER(CONVERT(nombre USING ASCII))='GRACIAS A DIOS';
UPDATE sag_departamentos SET codigo='10' WHERE codigo IS NULL AND UPPER(CONVERT(nombre USING ASCII))='INTIBUCA';
UPDATE sag_departamentos SET codigo='11' WHERE codigo IS NULL AND UPPER(CONVERT(nombre USING ASCII))='ISLAS DE LA BAHIA';
UPDATE sag_departamentos SET codigo='12' WHERE codigo IS NULL AND UPPER(CONVERT(nombre USING ASCII))='LA PAZ';
UPDATE sag_departamentos SET codigo='13' WHERE codigo IS NULL AND UPPER(CONVERT(nombre USING ASCII))='LEMPIRA';
UPDATE sag_departamentos SET codigo='14' WHERE codigo IS NULL AND UPPER(CONVERT(nombre USING ASCII))='OCOTEPEQUE';
UPDATE sag_departamentos SET codigo='15' WHERE codigo IS NULL AND UPPER(CONVERT(nombre USING ASCII))='OLANCHO';
UPDATE sag_departamentos SET codigo='16' WHERE codigo IS NULL AND UPPER(CONVERT(nombre USING ASCII))='SANTA BARBARA';
UPDATE sag_departamentos SET codigo='17' WHERE codigo IS NULL AND UPPER(CONVERT(nombre USING ASCII))='VALLE';
UPDATE sag_departamentos SET codigo='18' WHERE codigo IS NULL AND UPPER(CONVERT(nombre USING ASCII))='YORO';

-- Municipios
UPDATE sag_municipios m INNER JOIN sag_departamentos d ON d.id_departamento=m.id_departamento SET m.codigo='0108' WHERE m.codigo IS NULL AND UPPER(CONVERT(m.nombre USING ASCII))='ARIZONA' AND d.codigo='01';
UPDATE sag_municipios m INNER JOIN sag_departamentos d ON d.id_departamento=m.id_departamento SET m.codigo='0102' WHERE m.codigo IS NULL AND UPPER(CONVERT(m.nombre USING ASCII))='EL PORVENIR' AND d.codigo='01';
UPDATE sag_municipios m INNER JOIN sag_departamentos d ON d.id_departamento=m.id_departamento SET m.codigo='0103' WHERE m.codigo IS NULL AND UPPER(CONVERT(m.nombre USING ASCII))='ESPARTA' AND d.codigo='01';
UPDATE sag_municipios m INNER JOIN sag_departamentos d ON d.id_departamento=m.id_departamento SET m.codigo='0104' WHERE m.codigo IS NULL AND UPPER(CONVERT(m.nombre USING ASCII))='JUTIAPA' AND d.codigo='01';
UPDATE sag_municipios m INNER JOIN sag_departamentos d ON d.id_departamento=m.id_departamento SET m.codigo='0101' WHERE m.codigo IS NULL AND UPPER(CONVERT(m.nombre USING ASCII))='LA CEIBA' AND d.codigo='01';
UPDATE sag_municipios m INNER JOIN sag_departamentos d ON d.id_departamento=m.id_departamento SET m.codigo='0105' WHERE m.codigo IS NULL AND UPPER(CONVERT(m.nombre USING ASCII))='LA MASICA' AND d.codigo='01';
